import http from 'k6/http';
import { check } from 'k6';

export const options = {
  vus: 1,
  iterations: 1,
};

export default function () {
  const baseUrl = __ENV.BASE_URL;

  // Step 1: Login
  const loginRes = http.post(
    `${baseUrl}/login`,
    JSON.stringify({ username: 'bench', password: 'bench' }),
    { headers: { 'Content-Type': 'application/json' } }
  );
  check(loginRes, { 'login status 200': (r) => r.status === 200 });

  const loginBody = loginRes.json();
  const csrfToken = loginBody.csrf;
  check(loginRes, { 'csrf token present': () => csrfToken !== undefined && csrfToken !== '' });

  // Step 2: Get products
  const productsRes = http.get(`${baseUrl}/products`);
  check(productsRes, { 'products status 200': (r) => r.status === 200 });

  // Step 3: Add to cart
  const cartRes = http.post(
    `${baseUrl}/cart`,
    JSON.stringify({ product_id: 'sku-1' }),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrfToken,
      },
    }
  );
  check(cartRes, { 'cart status 200': (r) => r.status === 200 });

  // Step 4: Checkout
  const checkoutRes = http.post(
    `${baseUrl}/checkout`,
    JSON.stringify({}),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrfToken,
      },
    }
  );
  check(checkoutRes, { 'checkout status 200': (r) => r.status === 200 });
}
